function webConfigToRuntimeTheme(config) {
  const content = config?.website?.defaultContent || {};
  const vocab = config?.vocab || {};
  const label = config?.label || config?.key || 'Website';
  return {
    key: config.key,
    name: label,
    category: 'Static Website',
    industry: label,
    tags: [String(config.key || '').replace(/_/g, ' '), String(config.mood || '')].filter(Boolean),
    primaryColor: config.primaryColor || '#1F2937',
    bgColor: config.bgColor || '#FFFFFF',
    surfaceColor: config.surfaceColor || '#FFFFFF',
    textColor: config.textColor || '#111827',
    mutedColor: config.mutedColor || '#4B5563',
    accentColor: config.accentColor || config.primaryColor || '#4F46E5',
    borderColor: config.borderColor || '#E5E7EB',
    heroOverlayColor: 'rgba(17,24,39,0.72)',
    fontHeading: config.fontHeading || 'system-ui, -apple-system, sans-serif',
    fontBody: config.fontBody || 'system-ui, -apple-system, sans-serif',
    heroStyle: config.heroStyle || 'light',
    defaultThemeStyle: config.defaultThemeStyle,
    defaultDesignPreset: config.defaultDesignPreset,
    website: config.website || null,
    vocab: {
      appointment: vocab.contact || vocab.noun?.singular || 'enquiry',
      book: 'send',
      staff: vocab.staff || 'team',
      services: vocab.services || 'services',
      bookNow: vocab.bookNow || vocab.bookCta || content.ctaText || 'Send Enquiry',
      bookingConfirmed: vocab.confirmMsg || 'Enquiry sent',
      ctaQuestion: content.contactCtaBarTitle || 'Ready to start?',
      ...vocab,
    },
    defaultContent: {
      ctaText: vocab.bookNow || vocab.bookCta || 'Send Enquiry',
      ...content,
    },
  };
}

function relLuminance(hex) {
  if (typeof hex !== 'string') return 0;
  const h = hex.replace('#', '');
  const full = h.length === 3 ? h.split('').map((c) => c + c).join('') : h;
  if (full.length !== 6) return 0;
  const n = parseInt(full, 16);
  const srgb = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * srgb[0] + 0.7152 * srgb[1] + 0.0722 * srgb[2];
}

function isHexColor(hex) {
  return typeof hex === 'string' && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(hex.trim());
}

function normalizeHex(hex, fallback = '#000000') {
  if (!isHexColor(hex)) return fallback;
  const clean = hex.trim().replace('#', '');
  const full = clean.length === 3 ? clean.split('').map((c) => c + c).join('') : clean;
  return `#${full.toUpperCase()}`;
}

function contrastRatio(fgHex, bgHex) {
  const l1 = relLuminance(fgHex);
  const l2 = relLuminance(bgHex);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

function minContrastRatio(fgHex, bgHexes) {
  const backgrounds = Array.isArray(bgHexes) ? bgHexes : [bgHexes];
  return backgrounds.reduce((min, bgHex) => Math.min(min, contrastRatio(fgHex, bgHex)), Infinity);
}

function hexToRgb(hex) {
  const full = normalizeHex(hex, '#000000').slice(1);
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
  };
}

function rgbToHex({ r, g, b }) {
  const clamp = (value) => Math.max(0, Math.min(255, Math.round(value)));
  return `#${[clamp(r), clamp(g), clamp(b)]
    .map((v) => v.toString(16).padStart(2, '0'))
    .join('')
    .toUpperCase()}`;
}

function mixHex(a, b, weight = 0.5) {
  const ca = hexToRgb(a);
  const cb = hexToRgb(b);
  return rgbToHex({
    r: ca.r * (1 - weight) + cb.r * weight,
    g: ca.g * (1 - weight) + cb.g * weight,
    b: ca.b * (1 - weight) + cb.b * weight,
  });
}

function pickOnColor(bgHex) {
  const white = '#FFFFFF';
  const ink = '#111827';
  return contrastRatio(white, bgHex) >= contrastRatio(ink, bgHex) ? white : ink;
}

function improveTextContrastAcrossBackgrounds(fgHex, bgHexes, minRatio, fallbackHex) {
  const backgrounds = (Array.isArray(bgHexes) ? bgHexes : [bgHexes]).map((bgHex) => normalizeHex(bgHex, '#FFFFFF'));
  const preferred = normalizeHex(fgHex, fallbackHex || pickOnColor(backgrounds[0]));
  const seen = new Set();
  const candidates = [];

  const addCandidate = (value) => {
    if (!isHexColor(value)) return;
    const hex = normalizeHex(value, '#000000');
    if (seen.has(hex)) return;
    seen.add(hex);
    candidates.push(hex);
  };

  addCandidate(preferred);
  addCandidate(fallbackHex);
  backgrounds.forEach((bgHex) => addCandidate(pickOnColor(bgHex)));
  addCandidate('#111827');
  addCandidate('#0A0A0A');
  addCandidate('#FFFFFF');

  let best = preferred;
  let bestScore = minContrastRatio(preferred, backgrounds);

  for (const candidate of candidates) {
    const score = minContrastRatio(candidate, backgrounds);
    if (score >= minRatio) return candidate;
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  }

  for (const target of candidates) {
    for (let step = 1; step <= 10; step += 1) {
      const mixed = mixHex(preferred, target, step / 10);
      const score = minContrastRatio(mixed, backgrounds);
      if (score >= minRatio) return mixed;
      if (score > bestScore) {
        best = mixed;
        bestScore = score;
      }
    }
  }

  return best;
}

function improveBorderContrastAcrossBackgrounds(borderHex, bgHexes, minRatio = 1.25) {
  const backgrounds = (Array.isArray(bgHexes) ? bgHexes : [bgHexes]).map((bgHex) => normalizeHex(bgHex, '#FFFFFF'));
  const fallback = mixHex(backgrounds[backgrounds.length - 1], pickOnColor(backgrounds[backgrounds.length - 1]), 0.18);
  const preferred = normalizeHex(borderHex, fallback);
  const seen = new Set();
  const candidates = [];

  const addCandidate = (value) => {
    if (!isHexColor(value)) return;
    const hex = normalizeHex(value, '#000000');
    if (seen.has(hex)) return;
    seen.add(hex);
    candidates.push(hex);
  };

  addCandidate(preferred);
  backgrounds.forEach((bgHex) => {
    addCandidate(mixHex(bgHex, pickOnColor(bgHex), 0.14));
    addCandidate(mixHex(bgHex, pickOnColor(bgHex), 0.2));
    addCandidate(mixHex(bgHex, pickOnColor(bgHex), 0.26));
  });

  let best = preferred;
  let bestScore = minContrastRatio(preferred, backgrounds);

  for (const candidate of candidates) {
    const score = minContrastRatio(candidate, backgrounds);
    if (score >= minRatio) return candidate;
    if (score > bestScore) {
      best = candidate;
      bestScore = score;
    }
  }

  for (const target of candidates) {
    for (let step = 1; step <= 8; step += 1) {
      const mixed = mixHex(preferred, target, step / 8);
      const score = minContrastRatio(mixed, backgrounds);
      if (score >= minRatio) return mixed;
      if (score > bestScore) {
        best = mixed;
        bestScore = score;
      }
    }
  }

  return best;
}

function improveThemePair(bgHex, fgHex, minRatio = 4.5) {
  const bg = normalizeHex(bgHex, '#000000');
  const fg = improveTextContrastAcrossBackgrounds(fgHex, [bg], minRatio, pickOnColor(bg));
  return { bg, fg };
}

function harmonizeSurfaceTone(bgHex, surfaceHex) {
  const bg = normalizeHex(bgHex, '#FFFFFF');
  const surface = normalizeHex(surfaceHex, bg);

  if (pickOnColor(bg) === pickOnColor(surface)) {
    return contrastRatio(bg, surface) >= 1.08
      ? surface
      : mixHex(surface, pickOnColor(bg) === '#FFFFFF' ? '#FFFFFF' : '#0A0A0A', 0.04);
  }

  let best = surface;
  let bestScore = minContrastRatio(pickOnColor(bg), [bg, surface]);

  for (let step = 1; step <= 12; step += 1) {
    const mixed = mixHex(surface, bg, step / 12);
    const score = minContrastRatio(pickOnColor(bg), [bg, mixed]);
    if (score > bestScore) {
      best = mixed;
      bestScore = score;
    }
    if (pickOnColor(mixed) === pickOnColor(bg)) {
      return contrastRatio(bg, mixed) >= 1.08
        ? mixed
        : mixHex(mixed, pickOnColor(bg) === '#FFFFFF' ? '#FFFFFF' : '#0A0A0A', 0.04);
    }
  }

  return best;
}

function normalizeThemeContrast(theme) {
  const bgColor = normalizeHex(theme.bgColor, '#FFFFFF');
  const surfaceColor = harmonizeSurfaceTone(bgColor, theme.surfaceColor);
  const primaryColor = normalizeHex(theme.primaryColor, '#4F46E5');
  const accentColor = normalizeHex(theme.accentColor, primaryColor);
  const readingSurfaces = [bgColor, surfaceColor];

  const textColor = improveTextContrastAcrossBackgrounds(
    theme.textColor,
    readingSurfaces,
    4.5,
    pickOnColor(bgColor),
  );

  const bodyColor = improveTextContrastAcrossBackgrounds(
    theme.bodyColor || textColor,
    readingSurfaces,
    4.5,
    textColor,
  );

  const mutedColor = improveTextContrastAcrossBackgrounds(
    theme.mutedColor || bodyColor,
    readingSurfaces,
    3.25,
    bodyColor,
  );

  const borderBase = theme.borderColor || mixHex(surfaceColor, textColor, 0.14);
  const borderColor = improveBorderContrastAcrossBackgrounds(borderBase, readingSurfaces, 1.2);

  return {
    ...theme,
    primaryColor,
    accentColor,
    bgColor,
    surfaceColor,
    textColor,
    bodyColor,
    mutedColor,
    borderColor,
  };
}

function buildThemes(surfaceConfig, staticThemeConfigs) {
  const themes = { ...surfaceConfig.themes };
  if (surfaceConfig.includeStaticThemes) {
    for (const [key, config] of Object.entries(staticThemeConfigs || {})) {
      if (key === 'default' || !config?.key) continue;
      themes[key] = webConfigToRuntimeTheme(config);
    }

    for (const [legacyKey, staticKey] of Object.entries(STATIC_THEME_ALIASES)) {
      const config = staticThemeConfigs?.[staticKey];
      if (config) themes[legacyKey] = webConfigToRuntimeTheme({ ...config, key: legacyKey });
    }
  }
  return themes;
}

export function createProfessionThemeSurface(options = {}) {
  const surfaceConfig = SURFACES[options.surface] || SURFACES.shop;
  const THEMES = buildThemes(surfaceConfig, options.staticThemeConfigs);
  const THEME_CATEGORIES = surfaceConfig.themeCategories;
  const THEME_KEYS = Object.keys(THEMES);
  const PREMIUM_THEME_CONTENT_DEFAULTS = surfaceConfig.premiumThemeContentDefaults || {};

  function getThemesByCategory() {
    return Object.entries(THEME_CATEGORIES).map(([category, keys]) => ({
      category,
      themes: keys.map((key) => ({ key, ...THEMES[key] })),
    }));
  }

  function getTheme(key) {
    return THEMES[key] || THEMES[DEFAULT_PROFESSION_KEY];
  }

  function composeTheme(professionKey, styleKey = DEFAULT_STYLE_KEY, colorOverrides = null) {
    const profession = getTheme(professionKey);
    const styled = applyStyle(profession, styleKey);
    const overrides = sanitizeColorOverrides(colorOverrides);
    const theme = {
      ...styled,
      defaultContent: {
        ...(PREMIUM_THEME_CONTENT_DEFAULTS[profession.key] || {}),
        ...(styled.defaultContent || {}),
      },
      _profession: profession.key,
      _style: styleKey,
      ...(overrides.primary ? { primaryColor: overrides.primary } : {}),
      ...(overrides.accent ? { accentColor: overrides.accent } : {}),
      ...(overrides.surface ? { surfaceColor: overrides.surface } : {}),
      ...(overrides.bg ? { bgColor: overrides.bg } : {}),
      ...(overrides.text ? { textColor: overrides.text } : {}),
    };

    return normalizeThemeContrast(theme);
  }

  function getThemeVars(professionOrKey, styleKey, colorOverrides) {
    const theme = typeof professionOrKey === 'string'
      ? composeTheme(professionOrKey, styleKey, colorOverrides)
      : composeTheme(DEFAULT_PROFESSION_KEY, styleKey, colorOverrides);
    const strongSurface = mixHex(theme.primaryColor, pickOnColor(theme.primaryColor), 0.12);
    const strongPair = improveThemePair(strongSurface, pickOnColor(strongSurface), 4.5);
    const strongMuted = improveTextContrastAcrossBackgrounds(
      mixHex(strongPair.fg, strongPair.bg, 0.28),
      [strongPair.bg],
      3.25,
      strongPair.fg,
    );
    const strongBorder = improveBorderContrastAcrossBackgrounds(
      mixHex(strongPair.bg, strongPair.fg, 0.14),
      [strongPair.bg],
      1.2,
    );

    return {
      '--theme-primary': theme.primaryColor,
      '--theme-accent': theme.accentColor,
      '--theme-bg': theme.bgColor,
      '--theme-surface': theme.surfaceColor,
      '--theme-text': theme.textColor,
      '--theme-on-bg': pickOnColor(theme.bgColor),
      '--theme-on-surface': pickOnColor(theme.surfaceColor),
      '--theme-body': theme.bodyColor || theme.mutedColor,
      '--theme-muted': theme.mutedColor,
      '--theme-border': theme.borderColor,
      '--theme-on-primary': pickOnColor(theme.primaryColor),
      '--theme-on-accent': pickOnColor(theme.accentColor),
      '--theme-primary-soft': mixHex(theme.primaryColor, theme.bgColor, 0.88),
      '--theme-accent-soft': mixHex(theme.accentColor, theme.bgColor, 0.86),
      '--theme-strong': strongPair.bg,
      '--theme-on-strong': strongPair.fg,
      '--theme-strong-muted': strongMuted,
      '--theme-strong-border': strongBorder,
      '--font-heading': theme.fontHeading,
      '--font-body': theme.fontBody,
      '--font-accent': theme.fontAccent || theme.fontHeading,
    };
  }

  function resolveThemeKey(key) {
    if (THEMES[key]) return key;
    return LEGACY_MAP[key] || surfaceConfig.fallbackKey;
  }

  return {
    THEMES,
    THEME_CATEGORIES,
    THEME_KEYS,
    DEFAULT_PROFESSION_KEY,
    STYLES: SHARED_STYLES,
    getThemesByCategory,
    getTheme,
    composeTheme,
    getThemeVars,
    resolveThemeKey,
  };
}

export const STYLES = SHARED_STYLES;
export { DEFAULT_PROFESSION_KEY };
